  {"id":"tbi-4","topic":"Traumatic Brain Injury (TBI)","domain":"Internal medicine: emergency & acute care (cardiopulmonary resuscitation, trauma primary survey, toxicology & overdoses, environmental emergencies, anaphylaxis, acute abdomen)","discipline":"medicine","stem":"When is ICP monitoring indicated and when is it contraindicated in TBI?","answer":"Indicated: serial exams show impairment or elevated ICP risk. Contraindicated: conscious/alert patients; intentionally anticoagulated patients.","rationale":"ICP monitor insertion carries risk; benefit outweighs risk only when clinical monitoring is insufficient or ICP elevation is expected.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":1338}],"confusable_with":""},
  {"id":"tbi-5","topic":"Traumatic Brain Injury (TBI)","domain":"Internal medicine: emergency & acute care (cardiopulmonary resuscitation, trauma primary survey, toxicology & overdoses, environmental emergencies, anaphylaxis, acute abdomen)","discipline":"medicine","stem":"Head injuries contribute to what fraction of trauma deaths, and what percentage of TBI patients have associated injuries?","answer":"Up to 50% of trauma deaths; 10-40% of head injury patients have associated abdominal, thoracic, or long bone injuries.","rationale":"Multisystem trauma is common with TBI; concurrent injuries must be sought to avoid missed hemorrhage causing secondary brain insults.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":979}],"confusable_with":""},
  {"_type":"illness_script","topic":"Traumatic Brain Injury (TBI)","discipline":"medicine","enabling_conditions":"High-energy trauma (MVA, falls, assault, contact sports), young adults and elderly","pathophysiology":"Primary injury at moment of impact (contusion, axonal shear, vessel rupture); secondary injury from hypotension, hypoxia, elevated ICP, hemorrhage expansion, cerebral edema","time_course":"Primary injury immediate; secondary injury evolves over hours-days; delayed hematomas possible","key_features":"Altered consciousness, declining GCS motor score, signs of herniation (anisocoria, Cushing reflex), polytrauma","consequence_if_missed":"Undetected hypotension/hypoxia -> secondary injury; missed subdural -> herniation and death"}
